def point_in_triangle(p, a, b, c):
    # Function to compute the cross product of vectors (o, a) and (o, b)
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    # Compute vectors
    c1 = cross(a, b, p)
    c2 = cross(b, c, p)
    c3 = cross(c, a, p)

    # Point p is inside the triangle or on the edge if all cross products
    # have the same sign (all positive or all negative), or zero
    return (c1 >= 0 and c2 >= 0 and c3 >= 0) or (c1 <= 0 and c2 <= 0 and c3 <= 0)
