def point_in_triangle(p, a, b, c):
    def cross_product(o, a, b):
        # Calculate the cross product of vectors OA and OB
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    # Compute the cross products
    c1 = cross_product(p, a, b)
    c2 = cross_product(p, b, c)
    c3 = cross_product(p, c, a)

    # Check if the point is on the same side of all edges
    # (i.e., all cross products have the same sign or zero)
    if (c1 > 0 and c2 > 0 and c3 > 0) or (c1 < 0 and c2 < 0 and c3 < 0):
        return True
    # If any cross product is zero, the point is on an edge
    elif c1 == 0 or c2 == 0 or c3 == 0:
        return True
    else:
        return False
