def is_point_on_segment(p, a, b):
    # Check if point p lies on the line segment between a and b
    # First, check if p lies on the line defined by a and b
    # Then, check if it is between a and b

    # Check if the cross product is zero (collinear points)
    def cross_product(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    # Check if point p is between a and b (inclusive)
    def is_between(a, b, p):
        return (min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and
                min(a[1], b[1]) <= p[1] <= max(a[1], b[1]))

    # If cross product is zero, then p is collinear with a and b
    if cross_product(a, b, p) != 0:
        return False

    # If p is collinear, check if it is between a and b
    return is_between(a, b, p)
```

