def is_point_on_segment(p, a, b):
    # Check if point p lies on the line segment between a and b
    # First, check if p is collinear with a and b
    # Cross product of vectors ab and ap should be zero for collinearity
    def cross_product(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    # Check if p is between a and b (bounding box check)
    def is_between(a, b, p):
        return (min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and
                min(a[1], b[1]) <= p[1] <= max(a[1], b[1]))

    # If cross product is zero and p is between a and b, return True
    return cross_product(a, b, p) == 0 and is_between(a, b, p)
