def is_convex_polygon(points):
    def cross(o, a, b):
        # Compute the cross product of OA and OB vectors
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    n = len(points)
    if n < 3:
        return False  # A polygon must have at least 3 vertices

    # Check all consecutive triplets of points
    for i in range(n):
        a = points[i]
        b = points[(i + 1) % n]
        c = points[(i + 2) % n]
        # If the cross product changes sign, the polygon is concave
        if cross(a, b, c) < 0:
            return False

    # Check if all points are collinear
    # Use the first three points to check collinearity
    o, a, b = points[0], points[1], points[2]
    if cross(o, a, b) == 0:
        return False

    return True
```

