def equal_under_rotation(grid1, grid2):
    def rotate_90(grid):
        return [list(row)[::-1] for row in zip(*grid)]

    def rotate_180(grid):
        return [row[::-1] for row in grid[::-1]]

    def rotate_270(grid):
        return [list(row) for row in zip(*grid)][::-1]

    def are_equal(g1, g2):
        return g1 == g2

    rotations = [grid1, rotate_90(grid1), rotate_180(grid1), rotate_270(grid1)]
    return any(are_equal(r, grid2) for r in rotations)
```

