def is_checkerboard(grid):
    if not grid or not grid[0]:
        return True  # Empty grid or single cell is considered valid

    rows = len(grid)
    cols = len(grid[0])

    # Two possible values in a checkerboard pattern
    val1 = grid[0][0]
    val2 = grid[0][1] if cols > 1 else None
    val2 = grid[1][0] if rows > 1 else val2

    if val2 is None:
        return True  # Single cell grid

    # Check if all adjacent cells follow the checkerboard pattern
    for i in range(rows):
        for j in range(cols):
            current = grid[i][j]
            # Check top neighbor
            if i > 0 and grid[i-1][j] == current:
                return False
            # Check left neighbor
            if j > 0 and grid[i][j-1] == current:
                return False

    # Ensure exactly two distinct values are used
    unique_values = set()
    for row in grid:
        unique_values.update(row)
    if len(unique_values) != 2:
        return False

    return True
```

