def parse_url_parts(url):
    # Split the URL into scheme and the rest
    if '://' not in url:
        raise ValueError("URL must contain a scheme (e.g., 'http://')")

    scheme, rest = url.split('://', 1)

    # Split the rest into host and the remaining parts
    host_end = rest.find('/')
    if host_end == -1:
        host_end = rest.find('?')
    if host_end == -1:
        host = rest
        path = ''
        query = ''
    else:
        host = rest[:host_end]
        rest = rest[host_end:]

        # Split the rest into path and query
        if '?' in rest:
            path, query = rest.split('?', 1)
        else:
            path = rest
            query = ''

    return {
        'scheme': scheme,
        'host': host,
        'path': path,
        'query': query
    }
```

