def parse_url_parts(url):
    # Split the URL into scheme and the rest
    if '://' not in url:
        return {'scheme': '', 'host': '', 'path': '', 'query': ''}

    scheme, rest = url.split('://', 1)

    # Split the rest into host and the remaining parts
    host_end = rest.find('/')
    if host_end == -1:
        host_end = rest.find('?')
    if host_end == -1:
        host_end = len(rest)

    host = rest[:host_end]
    remaining = rest[host_end:]

    # Determine path and query
    if '?' in remaining:
        path_part, query = remaining.split('?', 1)
    else:
        path_part = remaining
        query = ''

    # Construct the result dictionary
    return {
        'scheme': scheme,
        'host': host,
        'path': path_part,
        'query': query
    }
```

