def parse_env_line(line):
    # Split the line into key and value parts based on the first '='
    if '=' not in line:
        return (line, '')  # No value provided, assume empty string

    key, value_part = line.split('=', 1)

    # Check if the value is quoted
    if len(value_part) >= 2:
        first_char = value_part[0]
        last_char = value_part[-1]
        if first_char == last_char and first_char in ('"', "'"):
            # Remove the surrounding quotes
            value = value_part[1:-1]
        else:
            value = value_part
    else:
        value = value_part

    return (key, value)
```

