def traffic_light_state(n_ticks, durations):
    red_ticks, green_ticks, yellow_ticks = durations
    total_cycle = red_ticks + green_ticks + yellow_ticks

    # Find the position within the cycle
    position = n_ticks % total_cycle

    if position < red_ticks:
        return "RED"
    elif position < red_ticks + green_ticks:
        return "GREEN"
    elif position < red_ticks + green_ticks + yellow_ticks:
        return "YELLOW"
    else:
        return "RED"  # This case shouldn't occur due to modulo
```

