def robot_grid_position(commands):
    x, y = 0, 0
    facing = 'N'  # initial direction

    # Mapping of directions and their changes in x and y when moving forward
    direction_map = {
        'N': (0, 1),
        'S': (0, -1),
        'E': (1, 0),
        'W': (-1, 0)
    }

    # Mapping of direction changes for left and right turns
    turn_map = {
        'L': {
            'N': 'W',
            'W': 'S',
            'S': 'E',
            'E': 'N'
        },
        'R': {
            'N': 'E',
            'E': 'S',
            'S': 'W',
            'W': 'N'
        }
    }

    for cmd in commands:
        if cmd == 'F':
            dx, dy = direction_map[facing]
            x += dx
            y += dy
        elif cmd == 'L' or cmd == 'R':
            facing = turn_map[cmd][facing]

    return (x, y, facing)
```

