    direction_vectors = {
        'N': (0, 1),
        'S': (0, -1),
        'E': (1, 0),
        'W': (-1, 0)
    }

    # Process each command
    for cmd in commands:
        if cmd == 'L':
            # Counter-clockwise turn: N -> W -> S -> E -> N
            facing = {'N': 'W', 'W': 'S', 'S': 'E', 'E': 'N'}[facing]
        elif cmd == 'R':
            # Clockwise turn: N -> E -> S -> W -> N
            facing = {'N': 'E', 'E': 'S', 'S': 'W', 'W': 'N'}[facing]
        elif cmd == 'F':
            dx, dy = direction_vectors[facing]
            x += dx
            y += dy

    return (x, y, facing)
