def rate_limiter_allowed(timestamps, limit, window):
    allowed = []
    request_times = []

    for t in timestamps:
        # Remove all timestamps that are outside the current window (t - window, t]
        while request_times and request_times[0] <= t - window:
            request_times.pop(0)

        # Check if the number of requests in the window is within the limit
        if len(request_times) < limit:
            allowed.append(True)
            request_times.append(t)
        else:
            allowed.append(False)

    return allowed
```

