def traffic_light_log(n_ticks, durations):
    red_ticks, green_ticks, yellow_ticks = durations
    cycle_length = red_ticks + green_ticks + yellow_ticks
    log = []

    for tick in range(n_ticks):
        cycle_position = tick % cycle_length
        if cycle_position < red_ticks:
            log.append("RED")
        elif cycle_position < red_ticks + green_ticks:
            log.append("GREEN")
        elif cycle_position < red_ticks + green_ticks + yellow_ticks:
            log.append("YELLOW")

    return log
```

