def shopping_cart_total(events):
    cart = {}  # Dictionary to store items: {item: (quantity, unit_price)}

    for event in events:
        if event[0] == "add":
            item, qty, price = event[1], event[2], event[3]
            if item in cart:
                existing_qty, existing_price = cart[item]
                # Update the price if the new price is different
                if existing_price != price:
                    existing_price = price
                cart[item] = (existing_qty + qty, existing_price)
            else:
                cart[item] = (qty, price)
        elif event[0] == "remove":
            item, qty = event[1], event[2]
            if item in cart:
                existing_qty, price = cart[item]
                if existing_qty > qty:
                    cart[item] = (existing_qty - qty, price)
                else:
                    del cart[item]
        elif event[0] == "clear":
            cart.clear()

    # Calculate total cost
    total = 0
    for item in cart:
        qty, price = cart[item]
        total += qty * price

    return total
```

