def robot_vacuum_cleaned(commands, obstacles):
    # Convert obstacles to a set for O(1) lookups
    obstacle_set = set(obstacles)

    # Initialize the robot's position and direction
    x, y = 0, 0
    direction = 'N'  # initial direction is North

    # Define the movement for each direction
    move = {
        'N': (0, 1),
        'E': (1, 0),
        'S': (0, -1),
        'W': (-1, 0)
    }

    # Define the direction changes for left and right turns
    turn_left = {
        'N': 'W',
        'W': 'S',
        'S': 'E',
        'E': 'N'
    }

    turn_right = {
        'N': 'E',
        'E': 'S',
        'S': 'W',
        'W': 'N'
    }

    # Set to keep track of cleaned cells
    cleaned = set()
    cleaned.add((x, y))

    for cmd in commands:
        if cmd == 'L':
            direction = turn_left[direction]
        elif cmd == 'R':
            direction = turn_right[direction]
        elif cmd == 'F':
            dx, dy = move[direction]
            new_x, new_y = x + dx, y + dy
            if (new_x, new_y) not in obstacle_set:
                x, y = new_x, new_y
            cleaned.add((x, y))

    return len(cleaned)
```

