def robot_vacuum_cleaned(commands, obstacles):
    # Convert obstacles to a set for O(1) lookups
    obstacle_set = set(obstacles)

    # Initialize robot's position and direction
    x, y = 0, 0
    direction = 'N'

    # Set of cleaned cells (including starting position)
    cleaned = {(x, y)}

    # Direction mappings
    directions = {
        'N': (0, 1),
        'E': (1, 0),
        'S': (0, -1),
        'W': (-1, 0)
    }

    # Turn mappings
    turn_map = {
        'L': {'N': 'W', 'W': 'S', 'S': 'E', 'E': 'N'},
        'R': {'N': 'E', 'E': 'S', 'S': 'W', 'W': 'N'}
    }

    for cmd in commands:
        if cmd == 'L' or cmd == 'R':
            # Update direction based on turn
            direction = turn_map[cmd][direction]
        elif cmd == 'F':
            # Calculate next position
            dx, dy = directions[direction]
            new_x, new_y = x + dx, y + dy

            # Check if new position is not an obstacle
            if (new_x, new_y) not in obstacle_set:
                x, y = new_x, new_y

        # Add current position to cleaned cells
        cleaned.add((x, y))

    return len(cleaned)
```

