def pedestrian_crossing_ticks(arrivals, red_duration, green_duration):
    crossing_ticks = []
    current_tick = 0
    while current_tick < max(arrivals) + red_duration + green_duration:
        # Determine the current light color
        light_cycle = (current_tick // (red_duration + green_duration))
        if current_tick % (red_duration + green_duration) < red_duration:
            light_color = 'RED'
        else:
            light_color = 'GREEN'

        # Check if any pedestrian can cross now
        for i in range(len(arrivals)):
            if arrivals[i] <= current_tick and light_color == 'RED':
                crossing_ticks.append(current_tick)
                arrivals[i] = -1  # Mark as processed
                break  # Only one pedestrian crosses at a time

        current_tick += 1

    return crossing_ticks
```

