        cycle_length = red + green + yellow
        tick_in_cycle = tick % cycle_length
        if tick_in_cycle < red:
            return 'RED'
        elif tick_in_cycle < red + green:
            return 'GREEN'
        else:
            return 'YELLOW'

    count = 0
    for t in range(n_ticks):
        if get_light_state(t, durations_a) == 'GREEN' and get_light_state(t, durations_b) == 'GREEN':
            count += 1
    return count
