def spiral_order(grid):
    if not grid or not grid[0]:
        return []

    result = []
    while grid:
        result.extend(grid[0])
        grid = [list(row)[1:] for row in grid]
        if not grid or not grid[0]:
            break
        for row in grid:
            result.append(row[-1])
        grid = [row[:-1] for row in grid]
        if not grid or not grid[0]:
            break
        result.extend(grid[-1][::-1])
        grid = [row[:-1] for row in grid]
        if not grid or not grid[0]:
            break
        for row in grid[::-1]:
            result.append(row[0])
        grid = [row[1:] for row in grid]

    return result
```

