        return []
    else:
        # Handle other cases by checking the number of requests in the window
        allowed = []
        for i, t in enumerate(timestamps):
            count = 0
            for j in range(i + 1):
                if timestamps[j] > t - window:
                    count += 1
            if count <= limit:
                allowed.append(True)
            else:
                allowed.append(False)
        return allowed
